"""Tests for the queries module: TaskQuery, TaskPage, apply_query."""

from __future__ import annotations

from datetime import datetime, timedelta, timezone

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from tasks_api.queries import TaskPage, TaskQuery, TaskQueryError, apply_query

NOW = datetime(2025, 6, 1, 12, 0, 0, tzinfo=timezone.utc)
PAST = NOW - timedelta(days=7)
FUTURE = NOW + timedelta(days=7)


def _task(id, title="task", status=TaskStatus.PENDING, priority=TaskPriority.MEDIUM,
          due_at=None, tags=None, created_at=None):
    return Task(
        id=id, title=title, status=status, priority=priority,
        due_at=due_at, created_at=created_at or NOW, tags=tags or [],
    )


TASKS = [
    _task(1, "Alpha", priority=TaskPriority.HIGH, created_at=NOW - timedelta(hours=3),
          tags=[Tag("work")]),
    _task(2, "Beta", priority=TaskPriority.LOW, due_at=PAST,
          created_at=NOW - timedelta(hours=2), tags=[Tag("home")]),
    _task(3, "Gamma", status=TaskStatus.DONE, priority=TaskPriority.MEDIUM,
          due_at=FUTURE, created_at=NOW - timedelta(hours=1)),
    _task(4, "Delta search-me", priority=TaskPriority.HIGH, due_at=FUTURE,
          created_at=NOW, tags=[Tag("work"), Tag("home")]),
]


class TestTaskQueryValidation:
    def test_invalid_sort_field(self):
        with pytest.raises(TaskQueryError, match="sort must be one of"):
            TaskQuery(sort="invalid")

    def test_limit_zero_raises(self):
        with pytest.raises(TaskQueryError, match="limit"):
            TaskQuery(limit=0)

    def test_limit_over_100_raises(self):
        with pytest.raises(TaskQueryError, match="limit"):
            TaskQuery(limit=101)

    def test_negative_offset_raises(self):
        with pytest.raises(TaskQueryError, match="offset"):
            TaskQuery(offset=-1)

    def test_tag_normalized(self):
        q = TaskQuery(tag="  Work  ")
        assert q.tag == "work"

    def test_invalid_tag_raises(self):
        with pytest.raises(ValueError):
            TaskQuery(tag="bad tag!")

    def test_search_whitespace_becomes_none(self):
        q = TaskQuery(search="   ")
        assert q.search is None

    def test_search_stripped(self):
        q = TaskQuery(search="  hello  ")
        assert q.search == "hello"

    def test_defaults(self):
        q = TaskQuery()
        assert q.sort == "created_at"
        assert q.descending is False
        assert q.limit == 20
        assert q.offset == 0


class TestTaskPage:
    def test_has_more_true(self):
        page = TaskPage(items=[_task(1)], total=5, limit=2, offset=0)
        assert page.has_more is True

    def test_has_more_false_exact(self):
        page = TaskPage(items=[_task(1), _task(2)], total=2, limit=2, offset=0)
        assert page.has_more is False

    def test_has_more_false_last_page(self):
        page = TaskPage(items=[_task(3)], total=3, limit=2, offset=2)
        assert page.has_more is False


class TestApplyQueryFilters:
    def test_no_filter(self):
        page = apply_query(TASKS, TaskQuery(), NOW)
        assert page.total == 4

    def test_filter_by_status_pending(self):
        page = apply_query(TASKS, TaskQuery(status=TaskStatus.PENDING), NOW)
        assert all(t.status == TaskStatus.PENDING for t in page.items)
        assert page.total == 3

    def test_filter_by_status_done(self):
        page = apply_query(TASKS, TaskQuery(status=TaskStatus.DONE), NOW)
        assert page.total == 1
        assert page.items[0].id == 3

    def test_filter_by_tag(self):
        page = apply_query(TASKS, TaskQuery(tag="work"), NOW)
        assert page.total == 2
        assert {t.id for t in page.items} == {1, 4}

    def test_filter_by_search(self):
        page = apply_query(TASKS, TaskQuery(search="search-me"), NOW)
        assert page.total == 1
        assert page.items[0].id == 4

    def test_search_case_insensitive(self):
        page = apply_query(TASKS, TaskQuery(search="ALPHA"), NOW)
        assert page.total == 1

    def test_filter_overdue_true(self):
        page = apply_query(TASKS, TaskQuery(overdue=True), NOW)
        assert page.total == 1
        assert page.items[0].id == 2

    def test_filter_overdue_false(self):
        page = apply_query(TASKS, TaskQuery(overdue=False), NOW)
        ids = {t.id for t in page.items}
        assert 2 not in ids
        assert page.total == 3

    def test_combined_filters(self):
        page = apply_query(
            TASKS, TaskQuery(status=TaskStatus.PENDING, tag="home"), NOW
        )
        assert page.total == 2
        assert {t.id for t in page.items} == {2, 4}


class TestApplyQuerySort:
    def test_sort_created_at_asc(self):
        page = apply_query(TASKS, TaskQuery(sort="created_at"), NOW)
        ids = [t.id for t in page.items]
        assert ids == [1, 2, 3, 4]

    def test_sort_created_at_desc(self):
        page = apply_query(TASKS, TaskQuery(sort="created_at", descending=True), NOW)
        ids = [t.id for t in page.items]
        assert ids == [4, 3, 2, 1]

    def test_sort_title(self):
        page = apply_query(TASKS, TaskQuery(sort="title"), NOW)
        titles = [t.title for t in page.items]
        assert titles == sorted(titles, key=str.lower)

    def test_sort_priority(self):
        page = apply_query(TASKS, TaskQuery(sort="priority"), NOW)
        keys = [TaskPriority.order_key(t.priority) for t in page.items]
        assert keys == sorted(keys)

    def test_sort_due_at(self):
        page = apply_query(TASKS, TaskQuery(sort="due_at"), NOW)
        # Tasks without due_at sort last
        assert page.items[-1].due_at is None or page.items[0].due_at is not None

    def test_sort_due_at_none_last(self):
        page = apply_query(TASKS, TaskQuery(sort="due_at"), NOW)
        none_indices = [i for i, t in enumerate(page.items) if t.due_at is None]
        non_none_indices = [i for i, t in enumerate(page.items) if t.due_at is not None]
        if none_indices and non_none_indices:
            assert min(none_indices) > max(non_none_indices)


class TestApplyQueryPagination:
    def test_limit(self):
        page = apply_query(TASKS, TaskQuery(limit=2), NOW)
        assert len(page.items) == 2
        assert page.total == 4
        assert page.has_more is True

    def test_offset(self):
        page = apply_query(TASKS, TaskQuery(limit=2, offset=2), NOW)
        assert len(page.items) == 2
        assert page.offset == 2

    def test_offset_beyond(self):
        page = apply_query(TASKS, TaskQuery(offset=100), NOW)
        assert len(page.items) == 0
        assert page.total == 4
        assert page.has_more is False

    def test_last_page(self):
        page = apply_query(TASKS, TaskQuery(limit=3, offset=3), NOW)
        assert len(page.items) == 1
        assert page.has_more is False

