class TestApplyQuerySort:
    def test_sort_created_at_asc(self):
        page = apply_query(TASKS, TaskQuery(sort="created_at"), NOW)
        ids = [t.id for t in page.items]
        assert ids == [1, 2, 3, 4]

    def test_sort_created_at_desc(self):
        page = apply_query(TASKS, TaskQuery(sort="created_at", descending=True), NOW)
        ids = [t.id for t in page.items]
        assert ids == [4, 3, 2, 1]

    def test_sort_title(self):
        page = apply_query(TASKS, TaskQuery(sort="title"), NOW)
        titles = [t.title for t in page.items]
        assert titles == sorted(titles, key=str.lower)

    def test_sort_priority(self):
        page = apply_query(TASKS, TaskQuery(sort="priority"), NOW)
        keys = [TaskPriority.order_key(t.priority) for t in page.items]
        assert keys == sorted(keys)

    def test_sort_due_at(self):
        page = apply_query(TASKS, TaskQuery(sort="due_at"), NOW)
        # Tasks without due_at sort last
        assert page.items[-1].due_at is None or page.items[0].due_at is not None

    def test_sort_due_at_none_last(self):
        page = apply_query(TASKS, TaskQuery(sort="due_at"), NOW)
        none_indices = [i for i, t in enumerate(page.items) if t.due_at is None]
        non_none_indices = [i for i, t in enumerate(page.items) if t.due_at is not None]
        if none_indices and non_none_indices:
            assert min(none_indices) > max(non_none_indices)


class TestApplyQueryPagination:
    def test_limit(self):
        page = apply_query(TASKS, TaskQuery(limit=2), NOW)
        assert len(page.items) == 2
        assert page.total == 4
        assert page.has_more is True

    def test_offset(self):
        page = apply_query(TASKS, TaskQuery(limit=2, offset=2), NOW)
        assert len(page.items) == 2
        assert page.offset == 2

    def test_offset_beyond(self):
        page = apply_query(TASKS, TaskQuery(offset=100), NOW)
        assert len(page.items) == 0
        assert page.total == 4
        assert page.has_more is False

    def test_last_page(self):
        page = apply_query(TASKS, TaskQuery(limit=3, offset=3), NOW)
        assert len(page.items) == 1
        assert page.has_more is False
